import{_ as l,o as i,c as t,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const D=JSON.parse('{"title":"CDS Infernalis (Day 2.2) -- LMDB backend for Ceph","description":"","frontmatter":{"title":"CDS Infernalis (Day 2.2) -- LMDB backend for Ceph","date":"2015-03-06T00:00:00.000Z","updated":"2015-03-07T00:00:00.000Z","tags":["Ceph","LMDB","SEF","Storage Efficiency Framework","分布式存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2015/CDS_Infernalis_Day_2.2_--_LMDB_backend_for_Ceph.md","filePath":"posts/2015/CDS_Infernalis_Day_2.2_--_LMDB_backend_for_Ceph.md","lastUpdated":1780459816000}'),n={name:"posts/2015/CDS_Infernalis_Day_2.2_--_LMDB_backend_for_Ceph.md"};function r(a,e,_,s,p,d){return i(),t("div",null,[...e[0]||(e[0]=[o("<p>会议纪要：</p><p><strong>会议主题</strong>： SEF（Storage Efficiency Framework）的LMDB键值存储后端方案讨论</p><p><strong>参会人员</strong>： Patrick、John（Intel）、Shinin、会议主持人</p><p><strong>会议内容</strong>：</p><ol><li><p><strong>方案概述</strong>：</p><ul><li>John介绍了LMDB（Lightning Memory-Mapped Database）作为SEF的键值存储后端方案。</li><li>当前SEF的QAL（Quota and Accounting Layer）实现存在问题，如读写放大率高，且需要将日志写入R Disc。</li><li>该方案将包括： <ol><li>实现<code>rmdb</code>存储类，继承自<code>qdb</code>，实现基本操作如get、delete和put。</li><li>集成<code>rmdb</code>作为子模块，支持自动配置和自动生成。</li><li>精炼<code>QB</code>接口，集成一些高级API，如合并操作、前缀迭代器等。</li></ol></li></ul></li><li><p><strong>方案讨论</strong>：</p><ul><li>会议认为尝试LMDB是值得的，可以了解其在键值存储中的表现。</li><li>目前SSD设置的性能问题主要在于RSM的压缩和读写放大。</li><li>建议不要过于依赖文件存储和键值存储的对比，因为它们的应用场景和性能特点不同。</li><li>新存储方案的目标是通用性，可在磁盘和SSD上良好运行，但不适合PCI附加的快速闪存等特定场景。</li></ul></li><li><p><strong>行动计划</strong>：</p><ul><li>尝试实现LMDB和LMDB接口，以便了解其在键值存储中的表现。</li><li>考虑将LMDB集成到监控器中，特别是读取方面。</li><li>使用现有的OSD测试工具进行测试，而不是尝试模拟OSD的工作负载。</li></ul></li><li><p><strong>其他讨论</strong>：</p><ul><li>讨论了在liberatus中是否需要构建键值接口，以及如何实现。</li><li>讨论了如何测试监控器特定的数据库，以及是否可以使用现有的测试工具。</li></ul></li></ol><p><strong>结论</strong>：</p><p>会议认为尝试LMDB作为SEF的键值存储后端方案是值得的，并制定了相应的行动计划。</p><p>[改进后的中文总结内容结束]</p>",8)])])}const S=l(n,[["render",r]]);export{D as __pageData,S as default};
